import type { PhosphorShape, PhosphorWeight } from '@lemonade/ui/phosphor/types'
import { withPrefix } from 'gatsby'

// Generated by `yarn phosphor:site-data` (runs automatically before `gatsby develop` / `gatsby build`).
import catalogData from '../../generated/phosphor-catalog.json'

export type { PhosphorShape, PhosphorWeight }

export interface PhosphorEntry {
  /** kebab-case name, e.g. `airplane-tilt` */
  name: string
  /** component exported by `@lemonade/ui/phosphor`, e.g. `PhAirplaneTilt` */
  component: string
  categories: string[]
  /** tags, including the `*new*` / `*updated*` markers used by Phosphor */
  tags: string[]
  codepoint: number
  published: number
  updated: number
  /** deprecated name kept by Phosphor for backwards compatibility */
  alias?: string
}

interface CatalogFile {
  version: string
  weights: PhosphorWeight[]
  icons: PhosphorEntry[]
}

const catalogFile = catalogData as CatalogFile

export const PHOSPHOR_VERSION = catalogFile.version
export const WEIGHTS: PhosphorWeight[] = catalogFile.weights
export const ICONS: PhosphorEntry[] = catalogFile.icons
export const ICONS_BY_NAME: Record<string, PhosphorEntry> = ICONS.reduce(
  (map, entry) => ({ ...map, [entry.name]: entry }),
  {} as Record<string, PhosphorEntry>
)

export const MARKER_TAGS = ['*new*', '*updated*']

export const isMarkerTag = (tag: string) => MARKER_TAGS.includes(tag)

export const CATEGORIES: Array<{ name: string; count: number }> = Object.entries(
  ICONS.reduce((counts, entry) => {
    entry.categories.forEach((category) => (counts[category] = (counts[category] || 0) + 1))
    return counts
  }, {} as Record<string, number>)
)
  .map(([name, count]) => ({ name, count }))
  .sort((a, b) => a.name.localeCompare(b.name))

export type WeightShapes = Record<string, PhosphorShape[]>

const weightCache = new Map<PhosphorWeight, Promise<WeightShapes>>()

/** Fetches (once) the SVG shapes of every icon for a weight — ~200 KB gzipped per weight. */
export function loadWeight(weight: PhosphorWeight): Promise<WeightShapes> {
  let request = weightCache.get(weight)
  if (!request) {
    request = fetch(withPrefix(`/phosphor/${weight}.json`))
      .then((response) => {
        if (!response.ok) {
          throw new Error(`Could not load Phosphor ${weight} icons (HTTP ${response.status})`)
        }
        return response.json()
      })
      .then((file: { icons: WeightShapes }) => file.icons)
    request.catch(() => weightCache.delete(weight))
    weightCache.set(weight, request)
  }
  return request
}

const HEX_COLOR = /^#([0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})$/i

export const isHexColor = (value: string) => HEX_COLOR.test(value)

/** Only hex colors and `currentColor` are accepted, so user input can never break out of the SVG markup. */
export const safeColor = (color: string) => (isHexColor(color) ? color : 'currentColor')

export function innerMarkup(shapes: PhosphorShape[]): string {
  return shapes
    .map((shape) =>
      typeof shape === 'string' ? `<path d="${shape}"/>` : `<path d="${shape[0]}" opacity="${shape[1]}"/>`
    )
    .join('')
}

export function svgMarkup(shapes: PhosphorShape[], size: number, color: string): string {
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" fill="${safeColor(color)}" ` +
    `viewBox="0 0 256 256">${innerMarkup(shapes)}</svg>`
  )
}

export function svgDataUrl(svg: string): string {
  return `data:image/svg+xml;base64,${btoa(unescape(encodeURIComponent(svg)))}`
}

export const fileName = (entry: PhosphorEntry, weight: PhosphorWeight, extension: string) =>
  `${entry.name}${weight === 'regular' ? '' : `-${weight}`}.${extension}`

export const formatCodepoint = (codepoint: number) => `U+${codepoint.toString(16).toUpperCase()}`
